// ─── constitution-context-rich.ts ────────────────────────────────────────────
// Deeper, fuller context for the Preamble and Articles I–VII, keyed by node id.
// These fields are merged over the base context in constitution-text.ts (see the
// enrich() pass there), replacing the shorter first-pass prose with richer,
// multi-sentence bilingual writing and longer case lists. The Amendments already
// carry rich context inline, so they are not listed here.

import type { ClauseContext } from "./constitution-text";

export const RICH_CONTEXT: Record<string, Partial<ClauseContext>> = {
  // ── Preamble ────────────────────────────────────────────────────────────────
  preamble: {
    plain: "The Constitution is enacted by the people themselves, not by the thirteen state governments, and it names six purposes for the new nation: to build a stronger union, deliver justice, keep peace at home, defend the country, promote the general welfare, and secure liberty for this generation and the ones to come. In a single sentence it announces both who is creating the government (\"We the People\") and why. It is the mission statement that everything after it is meant to carry out.",
    plainRo: "Constituția este adoptată de popor însuși, nu de cele treisprezece guverne statale, și numește șase scopuri pentru noua națiune: să construiască o uniune mai puternică, să facă dreptate, să păstreze pacea internă, să apere țara, să promoveze bunăstarea generală și să asigure libertatea pentru această generație și pentru cele viitoare. Într-o singură frază anunță și cine creează guvernul („Noi, Poporul”) și de ce. Este declarația de misiune pe care tot ce urmează trebuie să o îndeplinească.",
    history: "The soaring opening \"We the People\" was written by Gouverneur Morris on the Committee of Style in the final days of the 1787 Convention. An earlier draft began by listing the states one by one, but because no one knew which states would actually ratify, the phrase was generalized, and that accident of drafting carried enormous weight: it grounded the new government's authority in the people as a whole rather than in the states as sovereign parties to a treaty. Anti-Federalists like Patrick Henry attacked exactly this, asking \"Who authorized them to speak the language of We the People instead of We the States?\" The answer the Preamble gives, the people, became the foundation of American nationhood.",
    historyRo: "Începutul avântat „Noi, Poporul” a fost scris de Gouverneur Morris în Comitetul de Stil, în ultimele zile ale Convenției din 1787. O ciornă anterioară enumera statele unul câte unul, dar fiindcă nimeni nu știa ce state vor ratifica, formula a fost generalizată, iar acest accident de redactare a avut o greutate uriașă: a întemeiat autoritatea noului guvern pe popor ca întreg, nu pe state ca părți suverane ale unui tratat. Antifederaliști precum Patrick Henry au atacat exact acest lucru, întrebând „Cine i-a autorizat să vorbească limbajul Noi, Poporul în loc de Noi, Statele?” Răspunsul dat de Preambul, poporul, a devenit temelia națiunii americane.",
    cases: [
      { name: "Chisholm v. Georgia", year: "1793", note: "An early clash over whether \"the people\" or the states hold sovereignty; the states' reaction produced the 11th Amendment.", noteRo: "O ciocnire timpurie despre cine deține suveranitatea, poporul sau statele; reacția statelor a produs Amendamentul 11." },
      { name: "McCulloch v. Maryland", year: "1819", note: "Marshall leaned on \"We the People\" to argue the government sprang from the people, not the states, and could act directly on them.", noteRo: "Marshall s-a sprijinit pe „Noi, Poporul” pentru a argumenta că guvernul izvorăște din popor, nu din state, și poate acționa direct asupra lor." },
      { name: "Jacobson v. Massachusetts", year: "1905", note: "Cited the Preamble's purposes when upholding public-health powers, while noting it grants no power on its own.", noteRo: "A citat scopurile Preambulului când a confirmat puterile de sănătate publică, notând că el nu acordă putere prin sine." },
    ],
    examples: "The Preamble carries no enforceable power of its own, yet it is quoted constantly, on the walls of monuments, in presidential speeches, and in briefs, whenever someone argues what the whole enterprise is for. Schoolchildren memorize it; courts treat its stated goals as a guide to reading the text that follows. When Americans invoke \"a more perfect Union\" or \"the general Welfare,\" they are reaching for this sentence.",
    examplesRo: "Preambulul nu are o putere aplicabilă proprie, dar este citat constant, pe zidurile monumentelor, în discursurile prezidențiale și în memorii juridice, ori de câte ori cineva argumentează pentru ce există întregul demers. Copiii îl memorează; instanțele îi tratează scopurile declarate ca ghid pentru citirea textului care urmează. Când americanii invocă „o uniune mai perfectă” sau „bunăstarea generală”, apelează la această frază.",
    debates: "Because it lists sweeping aims like \"the general Welfare\" and \"a more perfect Union,\" some read the Preamble as evidence that the federal government was meant to have broad, purposive power. Others insist it is purely a statement of intent that confers no authority whatsoever, and the Supreme Court has generally agreed with the latter. The deeper argument it still fuels is about national identity: whether the union is a compact among sovereign states that can be undone, or a single people that is permanent, a question the Civil War answered in blood.",
    debatesRo: "Fiindcă enumeră scopuri largi precum „bunăstarea generală” și „o uniune mai perfectă”, unii citesc Preambulul ca dovadă că guvernul federal trebuia să aibă o putere largă, orientată spre scop. Alții insistă că e pur o declarație de intenție care nu conferă nicio autoritate, iar Curtea Supremă a fost în general de acord cu ultima. Argumentul mai profund pe care încă îl alimentează privește identitatea națională: dacă uniunea e un pact între state suverane care poate fi desfăcut, sau un singur popor care e permanent, o întrebare la care Războiul Civil a răspuns cu sânge.",
  },

  // ── Article I ────────────────────────────────────────────────────────────────
  "art1-s1": {
    plain: "Every lawmaking power the Constitution grants belongs to Congress, and Congress is split into two chambers, the Senate and the House of Representatives. The phrase \"herein granted\" is quietly crucial: it signals that Congress holds only the powers the Constitution lists, not a general authority to do anything it wishes. Everything Congress does must trace back to an enumerated power.",
    plainRo: "Fiecare putere de a face legi pe care o acordă Constituția aparține Congresului, iar Congresul e împărțit în două camere, Senatul și Camera Reprezentanților. Sintagma „aici acordate” e discret esențială: arată că Congresul deține doar puterile enumerate de Constituție, nu o autoritate generală de a face orice dorește. Tot ce face Congresul trebuie să se lege de o putere enumerată.",
    history: "The two-chamber design was the Great Compromise that saved the Convention: a House apportioned by population satisfied the large states, while a Senate with equal votes per state satisfied the small ones. Splitting the legislature in two was also a deliberate brake on hasty lawmaking, forcing every bill to survive two different bodies with different constituencies and rhythms. The opening words \"All legislative Powers herein granted\" set up the entire theory of a limited national government of enumerated powers.",
    historyRo: "Structura cu două camere a fost Marele Compromis care a salvat Convenția: o Cameră repartizată după populație a mulțumit statele mari, iar un Senat cu voturi egale pentru fiecare stat le-a mulțumit pe cele mici. Împărțirea legislativului în două a fost și o frână deliberată împotriva legiferării pripite, obligând fiecare proiect să supraviețuiască în două corpuri diferite, cu electorate și ritmuri diferite. Cuvintele de început „Toate puterile legislative aici acordate” instituie întreaga teorie a unui guvern național limitat, cu puteri enumerate.",
    cases: [
      { name: "INS v. Chadha", year: "1983", note: "Struck down the one-house \"legislative veto\": to make law, Congress must use the full bicameral process and presentment.", noteRo: "A anulat „vetoul legislativ” dintr-o singură cameră: pentru a face lege, Congresul trebuie să folosească întregul proces bicameral și prezentarea." },
      { name: "Clinton v. City of New York", year: "1998", note: "The line-item veto is unconstitutional; a president cannot edit statutes Congress passed.", noteRo: "Vetoul pe articole e neconstituțional; un președinte nu poate edita legile adoptate de Congres." },
      { name: "Gundy v. United States", year: "2019", note: "A fractured Court signaled new interest in reviving limits on how much lawmaking Congress may delegate to agencies.", noteRo: "O Curte divizată a semnalat un nou interes de a reînvia limitele privind cât din legiferare poate delega Congresul agențiilor." },
    ],
    examples: "The nondelegation debate lives in this sentence: how much rule-writing Congress may hand to federal agencies like the EPA or SEC before it is effectively giving away its own legislative power. Every major regulation, and every fight over whether an agency exceeded what Congress authorized, ultimately traces to \"All legislative Powers.\"",
    examplesRo: "Dezbaterea nondelegării trăiește în această frază: cât din scrierea regulilor poate ceda Congresul agențiilor federale precum EPA sau SEC înainte de a-și da efectiv propria putere legislativă. Fiecare reglementare majoră și fiecare dispută despre dacă o agenție a depășit ce a autorizat Congresul se leagă în final de „Toate puterile legislative”.",
    debates: "\"All legislative Powers\" is the battleground of the modern administrative state. Critics argue that federal agencies now write binding rules that are laws in everything but name, an unconstitutional transfer of Congress's job. Defenders reply that a continental government simply cannot function if Congress must spell out every detail, and that delegating the details while keeping the big choices is both practical and constitutional. The Supreme Court has recently shown appetite for policing that line more strictly than it has since the 1930s.",
    debatesRo: "„Toate puterile legislative” e câmpul de luptă al statului administrativ modern. Criticii susțin că agențiile federale scriu acum reguli obligatorii care sunt legi în tot afară de nume, un transfer neconstituțional al sarcinii Congresului. Apărătorii răspund că un guvern continental pur și simplu nu poate funcționa dacă Congresul trebuie să detalieze totul și că delegarea detaliilor păstrând marile alegeri e și practică și constituțională. Curtea Supremă a arătat recent apetit pentru a controla acea linie mai strict decât din anii 1930.",
  },
  "art1-s2": {
    plain: "The House of Representatives is the chamber closest to the people: its members are elected directly every two years, and each state's share of seats is set by population, counted in a census every ten years. To serve, you must be at least 25, a citizen for seven years, and live in the state you represent. The House also holds one weapon the Senate does not, the sole power to impeach federal officials.",
    plainRo: "Camera Reprezentanților e camera cea mai apropiată de popor: membrii ei sunt aleși direct la fiecare doi ani, iar cota de locuri a fiecărui stat e stabilită după populație, numărată printr-un recensământ la fiecare zece ani. Pentru a servi, trebuie să ai cel puțin 25 de ani, să fii cetățean de șapte ani și să locuiești în statul pe care îl reprezinți. Camera deține și o armă pe care Senatul nu o are, puterea exclusivă de a pune sub acuzare oficiali federali.",
    history: "The two-year term was meant to keep the House tightly tied to the popular mood, the branch that would feel the public's temper first. The infamous three-fifths clause counted each enslaved person as three-fifths of a human for apportionment, a grim bargain that inflated Southern power in both the House and the Electoral College for seventy years, until the 14th Amendment erased it and the census began counting \"the whole number of persons.\" The decennial census the clause requires has become one of the most consequential recurring events in American government.",
    historyRo: "Mandatul de doi ani trebuia să țină Camera strâns legată de starea de spirit populară, ramura care ar simți prima temperamentul publicului. Infama clauză a celor trei cincimi număra fiecare persoană înrobită drept trei cincimi dintr-un om pentru repartizare, un târg sumbru care a umflat puterea Sudului atât în Cameră, cât și în Colegiul Electoral timp de șaptezeci de ani, până când Amendamentul 14 a șters-o și recensământul a început să numere „numărul total de persoane”. Recensământul decenal cerut de clauză a devenit unul dintre cele mai importante evenimente recurente din guvernarea americană.",
    cases: [
      { name: "Wesberry v. Sanders", year: "1964", note: "\"One person, one vote\": House districts within a state must be nearly equal in population.", noteRo: "„Un om, un vot”: districtele Camerei dintr-un stat trebuie să fie aproape egale ca populație." },
      { name: "U.S. Term Limits v. Thornton", year: "1995", note: "States cannot add qualifications for Congress beyond age, citizenship, and residence.", noteRo: "Statele nu pot adăuga calificări pentru Congres dincolo de vârstă, cetățenie și rezidență." },
      { name: "Rucho v. Common Cause", year: "2019", note: "Partisan gerrymandering claims are political questions federal courts cannot resolve.", noteRo: "Plângerile privind gerrymandering-ul partizan sunt chestiuni politice pe care instanțele federale nu le pot soluționa." },
      { name: "Department of Commerce v. New York", year: "2019", note: "Blocked a citizenship question on the census, showing how high the stakes of the count are.", noteRo: "A blocat o întrebare despre cetățenie la recensământ, arătând cât de mari sunt mizele numărătorii." },
    ],
    examples: "Every decade the census sets off reapportionment, states gaining or losing seats, and then the redistricting fights and gerrymandering lawsuits that follow. Impeachments of presidents, judges, and cabinet officers all begin in the House under this section. Control of the House, redrawn every ten years, shapes national policy for a decade at a time.",
    examplesRo: "În fiecare deceniu recensământul declanșează redistribuirea, state care câștigă sau pierd locuri, și apoi luptele de retrasare a districtelor și procesele privind gerrymandering-ul. Punerile sub acuzare ale președinților, judecătorilor și miniștrilor încep toate în Cameră sub această secțiune. Controlul Camerei, retrasat la fiecare zece ani, modelează politica națională pentru câte un deceniu.",
    debates: "Partisan gerrymandering, drawing district lines to lock in one party's advantage, is the fiercest fight built on this section, and after Rucho the federal courts have stepped aside, leaving it to states. A second running argument is over who the census may count and how: whether to include noncitizens, how to handle prisoners, and how undercounts shift both House seats and federal dollars away from some communities.",
    debatesRo: "Gerrymandering-ul partizan, trasarea liniilor districtuale pentru a bloca avantajul unui partid, e cea mai aprigă luptă construită pe această secțiune, iar după Rucho instanțele federale s-au retras, lăsând-o statelor. Un al doilea argument continuu privește pe cine poate număra recensământul și cum: dacă să includă necetățeni, cum să trateze deținuții și cum subnumărările deplasează atât locurile din Cameră, cât și banii federali departe de unele comunități.",
  },
  "art1-s3": {
    plain: "Each state gets exactly two Senators, no matter its size, elected to six-year terms, with only a third of the Senate up for election every two years so the body is never entirely new. The Vice President presides over the Senate but votes only to break a tie. And the Senate alone holds the impeachment trial: it needs a two-thirds vote to remove an official, a deliberately high bar.",
    plainRo: "Fiecare stat are exact doi senatori, indiferent de mărime, aleși pe mandate de șase ani, cu doar o treime din Senat în alegeri la fiecare doi ani, astfel încât corpul să nu fie niciodată complet nou. Vicepreședintele prezidează Senatul, dar votează doar pentru a decide la egalitate. Iar Senatul singur ține procesul de destituire: are nevoie de două treimi pentru a înlătura un oficial, un prag deliberat ridicat.",
    history: "Equal representation, two Senators per state regardless of population, was the price small states demanded to join the union, and it is the single provision the Constitution declares can never be stripped from a state without its consent. The six-year staggered terms were designed to make the Senate a cooler, more continuous, more deliberate counterweight to the fast-changing House, a body Madison hoped would \"proceed with more coolness, with more system, and with more wisdom.\" Until 1913 Senators were chosen by state legislatures, not voters.",
    historyRo: "Reprezentarea egală, doi senatori pentru fiecare stat indiferent de populație, a fost prețul cerut de statele mici pentru a se alătura uniunii și e singura prevedere despre care Constituția declară că nu poate fi luată niciodată de la un stat fără consimțământul său. Mandatele eșalonate de șase ani au fost concepute pentru a face din Senat un contragreutate mai calmă, mai continuă și mai deliberativă față de Camera care se schimbă rapid, un corp despre care Madison spera că va „proceda cu mai multă răceală, mai mult sistem și mai multă înțelepciune”. Până în 1913 senatorii erau aleși de legislaturile statale, nu de alegători.",
    cases: [
      { name: "Nixon v. United States", year: "1993", note: "How the Senate conducts an impeachment trial is a \"political question\" the courts will not review.", noteRo: "Modul în care Senatul conduce un proces de destituire e o „chestiune politică” pe care instanțele nu o revizuiesc." },
      { name: "Coleman v. Miller", year: "1939", note: "Reinforced that many questions about the Senate's internal procedures rest with the Senate, not judges.", noteRo: "A întărit că multe întrebări despre procedurile interne ale Senatului aparțin Senatului, nu judecătorilor." },
    ],
    examples: "Three presidents, Andrew Johnson, Bill Clinton, and Donald Trump (twice), have been impeached by the House, and none was convicted, because reaching 67 Senate votes across party lines is extraordinarily hard. The Vice President's tie-breaking vote regularly decides evenly split Senates, confirming nominees and passing landmark bills. Every treaty and every Supreme Court justice also passes through this chamber.",
    examplesRo: "Trei președinți, Andrew Johnson, Bill Clinton și Donald Trump (de două ori), au fost puși sub acuzare de Cameră, și niciunul nu a fost condamnat, fiindcă atingerea a 67 de voturi în Senat peste liniile de partid e extraordinar de grea. Votul decisiv al Vicepreședintelui decide în mod regulat Senaturile împărțite egal, confirmând nominalizări și adoptând legi de referință. Fiecare tratat și fiecare judecător al Curții Supreme trece de asemenea prin această cameră.",
    debates: "Equal state suffrage is attacked as deeply anti-majoritarian: a voter in Wyoming has roughly seventy times the Senate weight of a voter in California, and small rural states can block what large majorities of Americans want. Defenders answer that this is the essential guarantee of a federal, not merely national, union, the very deal that made a country possible, and one the Constitution places beyond the reach of ordinary amendment.",
    debatesRo: "Votul egal al statelor e atacat ca profund anti-majoritar: un alegător din Wyoming are aproximativ de șaptezeci de ori greutatea în Senat a unuia din California, iar statele rurale mici pot bloca ce vor majorități mari de americani. Apărătorii răspund că aceasta e garanția esențială a unei uniuni federale, nu doar naționale, chiar înțelegerea care a făcut posibilă o țară, și una pe care Constituția o plasează dincolo de amendamentul obișnuit.",
  },
  "art1-s4": {
    plain: "States get the first say over the time, place, and manner of congressional elections, but Congress can step in and override those rules whenever it chooses. The section also requires Congress to meet at least once a year. Together these clauses make sure elections actually happen and the legislature actually convenes.",
    plainRo: "Statele au primul cuvânt asupra timpului, locului și modului alegerilor pentru Congres, dar Congresul poate interveni și anula aceste reguli oricând dorește. Secțiunea cere de asemenea Congresului să se întrunească cel puțin o dată pe an. Împreună, aceste clauze asigură că alegerile chiar au loc și că legislativul chiar se convoacă.",
    history: "The Elections Clause gives states the opening move but hands Congress the last word, a safeguard the Framers added precisely so that a hostile state could not quietly strangle the federal legislature by simply refusing to hold elections. It is the constitutional foundation for national election law. The annual-meeting requirement guaranteed that Congress could not be sidelined the way the King had prorogued Parliament.",
    historyRo: "Clauza Alegerilor dă statelor mutarea de deschidere, dar îi dă Congresului ultimul cuvânt, o garanție pe care Fondatorii au adăugat-o tocmai pentru ca un stat ostil să nu poată sugruma discret legislativul federal refuzând pur și simplu să organizeze alegeri. E temelia constituțională a legii electorale naționale. Cerința întrunirii anuale garanta că Congresul nu putea fi marginalizat așa cum Regele suspenda Parlamentul.",
    cases: [
      { name: "Arizona State Legislature v. Arizona Ind. Redistricting Comm'n", year: "2015", note: "\"The Legislature\" can include the people acting by ballot initiative, upholding independent redistricting commissions.", noteRo: "„Legislatura” poate include poporul care acționează prin inițiativă, confirmând comisiile independente de redistribuire." },
      { name: "Moore v. Harper", year: "2023", note: "Rejected the strong \"independent state legislature\" theory; state courts and constitutions still bind legislatures on federal election rules.", noteRo: "A respins teoria puternică a „legislaturii statale independente”; instanțele și constituțiile statale încă obligă legislaturile la regulile electorale federale." },
    ],
    amendments: ["amend-17", "amend-20"],
    examples: "National statutes like the Voting Rights Act, the National Voter Registration Act, and the uniform November election day all rest on Congress's override power in this clause. When states set voter-ID rules, mail-ballot deadlines, or precinct locations, they act first under this section, subject to Congress and the courts.",
    examplesRo: "Legi naționale precum Voting Rights Act, National Voter Registration Act și ziua uniformă de alegeri din noiembrie se sprijină toate pe puterea de anulare a Congresului din această clauză. Când statele stabilesc reguli de identificare a alegătorilor, termene pentru votul prin corespondență sau locațiile secțiilor, ele acționează primele sub această secțiune, sub rezerva Congresului și a instanțelor.",
    debates: "The \"independent state legislature\" theory, the claim that state courts and state constitutions cannot check legislatures when they write rules for federal elections, became a major flashpoint after 2020 and was largely rejected in Moore v. Harper. The unresolved edge is how far Congress should go in setting national election standards versus leaving elections to the states, a fight that flares with every federal voting-rights bill.",
    debatesRo: "Teoria „legislaturii statale independente”, afirmația că instanțele și constituțiile statale nu pot controla legislaturile când scriu regulile pentru alegerile federale, a devenit un punct major de tensiune după 2020 și a fost respinsă în mare parte în Moore v. Harper. Marginea nerezolvată e cât de departe ar trebui să meargă Congresul în stabilirea standardelor electorale naționale față de a lăsa alegerile statelor, o luptă care izbucnește la fiecare proiect federal privind drepturile de vot.",
  },
  "art1-s5": {
    plain: "Each chamber runs itself: it judges whether its own members were properly elected and qualified, writes its own rules of procedure, can punish members and even expel one by a two-thirds vote, and must keep and publish a journal of what it does. A majority is needed to do business (a quorum), and neither chamber can take a long break without the other's consent.",
    plainRo: "Fiecare cameră se conduce singură: judecă dacă proprii membri au fost aleși și calificați corect, își scrie propriile reguli de procedură, își poate pedepsi membrii și chiar poate exclude unul cu două treimi și trebuie să țină și să publice un jurnal al lucrărilor sale. E nevoie de o majoritate pentru a lucra (un cvorum), iar niciuna dintre camere nu poate lua o pauză lungă fără consimțământul celeilalte.",
    history: "These self-governance powers make each chamber master of its own house, insulated from the other branches in how it operates. The Senate filibuster, the practice that in effect requires sixty votes to end debate on most bills, is not in the Constitution at all; it grew entirely out of \"Each House may determine the Rules of its Proceedings.\" The journal requirement was an early transparency mandate, forcing Congress to record how members voted.",
    historyRo: "Aceste puteri de autoguvernare fac fiecare cameră stăpână pe propria casă, izolată de celelalte ramuri în modul în care funcționează. Filibuster-ul din Senat, practica ce cere în fapt șaizeci de voturi pentru a încheia dezbaterea la majoritatea proiectelor, nu e deloc în Constituție; a crescut în întregime din „Fiecare cameră își poate stabili regulile procedurilor”. Cerința jurnalului a fost un mandat timpuriu de transparență, obligând Congresul să consemneze cum au votat membrii.",
    cases: [
      { name: "Powell v. McCormack", year: "1969", note: "The House may judge only the three constitutional qualifications; it cannot exclude a duly elected member it dislikes.", noteRo: "Camera poate judeca doar cele trei calificări constituționale; nu poate exclude un membru ales legal care nu-i place." },
      { name: "United States v. Ballin", year: "1892", note: "Each House has wide latitude to set its own rules, so long as it does not violate the Constitution.", noteRo: "Fiecare cameră are o marjă largă de a-și stabili regulile, atâta timp cât nu încalcă Constituția." },
    ],
    examples: "The Senate filibuster, the House and Senate ethics committees, expulsion votes, and the published Congressional Record all flow directly from this section. When a chamber disciplines, censures, or expels a member, or fights over changing its rules, it is exercising powers written here.",
    examplesRo: "Filibuster-ul din Senat, comisiile de etică ale Camerei și Senatului, voturile de excludere și Congressional Record publicat decurg toate direct din această secțiune. Când o cameră sancționează, mustrează sau exclude un membru, ori se ceartă pe schimbarea regulilor, ea exercită puteri scrise aici.",
    debates: "Whether the filibuster should survive is one of the loudest recurring fights in Washington: critics say it lets a minority strangle the majority rule the Constitution otherwise assumes, while defenders say it forces compromise and protects the minority in a chamber already built to slow things down. Because it is only a Senate rule, a simple majority could abolish it at any time, which keeps the \"nuclear option\" perpetually on the table.",
    debatesRo: "Dacă filibuster-ul ar trebui să supraviețuiască e una dintre cele mai zgomotoase lupte recurente din Washington: criticii spun că permite unei minorități să sugrume regula majorității pe care Constituția o presupune altfel, iar apărătorii spun că forțează compromisul și protejează minoritatea într-o cameră deja construită să încetinească lucrurile. Fiindcă e doar o regulă a Senatului, o majoritate simplă ar putea-o desființa oricând, ceea ce ține „opțiunea nucleară” permanent pe masă.",
  },
  "art1-s6": {
    plain: "Members of Congress are paid from the national Treasury and are shielded by the Speech or Debate Clause: they cannot be sued or prosecuted for anything they say as part of the legislative process. They also cannot be arrested on the way to Congress (except for serious crimes), and they cannot hold another federal office at the same time as their seat.",
    plainRo: "Membrii Congresului sunt plătiți din Trezoreria națională și sunt protejați de Clauza Discursului sau Dezbaterii: nu pot fi dați în judecată sau urmăriți penal pentru nimic din ce spun ca parte a procesului legislativ. De asemenea, nu pot fi arestați în drum spre Congres (cu excepția infracțiunilor grave) și nu pot deține o altă funcție federală în același timp cu locul lor.",
    history: "The Speech or Debate Clause is inherited almost directly from the English Bill of Rights of 1689, born from centuries of monarchs jailing legislators for defiant speeches; it lets members debate, investigate, and accuse without fear of a hostile prosecutor or president. The Incompatibility Clause, barring members from holding executive office at the same time, is a cornerstone of the separation of powers, deliberately breaking with Britain, where ministers sit in Parliament.",
    historyRo: "Clauza Discursului sau Dezbaterii e moștenită aproape direct din Declarația Drepturilor engleză din 1689, născută din secole de monarhi care întemnițau legislatori pentru discursuri sfidătoare; le permite membrilor să dezbată, să investigheze și să acuze fără teama unui procuror sau președinte ostil. Clauza Incompatibilității, care interzice membrilor să dețină o funcție executivă în același timp, e o piatră de temelie a separării puterilor, rupând deliberat cu Marea Britanie, unde miniștrii stau în Parlament.",
    cases: [
      { name: "Gravel v. United States", year: "1972", note: "The clause shields a senator and his aides for legislative acts, but not for arranging private publication.", noteRo: "Clauza protejează un senator și asistenții săi pentru acte legislative, dar nu pentru aranjarea publicării private." },
      { name: "Powell v. McCormack", year: "1969", note: "Speech or Debate immunity is broad but does not let the House ignore members' constitutional rights.", noteRo: "Imunitatea Discursului sau Dezbaterii e largă, dar nu permite Camerei să ignore drepturile constituționale ale membrilor." },
    ],
    amendments: ["amend-27"],
    examples: "The Speech or Debate Clause is why a member can read classified documents into the record, level accusations on the floor, or run an aggressive investigation without being sued for defamation or hauled into court over it. The clause also frustrates prosecutors and civil plaintiffs who try to use a lawmaker's official words against them.",
    examplesRo: "Datorită Clauzei Discursului sau Dezbaterii, un membru poate citi documente clasificate în procesul-verbal, poate lansa acuzații în plen sau poate conduce o investigație agresivă fără a fi dat în judecată pentru defăimare sau târât în instanță. Clauza îi frustrează și pe procurorii și reclamanții civili care încearcă să folosească cuvintele oficiale ale unui legiuitor împotriva lui.",
    debates: "The 27th Amendment, ratified in 1992 after sitting unratified for over two centuries, grew straight out of this pay clause: it delays any congressional pay raise until after the next election, so members cannot vote themselves an immediate raise. A live modern question is how far Speech or Debate immunity reaches into staff work, fact-finding trips, and press activity, and whether it can shield genuinely corrupt conduct.",
    debatesRo: "Amendamentul 27, ratificat în 1992 după ce a stat neratificat peste două secole, a crescut direct din această clauză de salarizare: amână orice majorare a salariilor Congresului până după următoarele alegeri, ca membrii să nu-și poată vota o majorare imediată. O întrebare modernă vie e cât de departe ajunge imunitatea Discursului sau Dezbaterii în munca personalului, în deplasările de documentare și în activitatea de presă, și dacă poate proteja o conduită cu adevărat coruptă.",
  },
  "art1-s7": {
    plain: "Tax bills must start in the House, the chamber closest to the people. Any bill has to pass both chambers in identical form and then go to the President, who can sign it into law, veto it, or, if he does nothing for ten days while Congress is in session, let it become law. Congress can override a veto, but only with a two-thirds vote in each chamber.",
    plainRo: "Proiectele fiscale trebuie să înceapă în Cameră, camera cea mai apropiată de popor. Orice proiect trebuie să treacă de ambele camere în formă identică și apoi să meargă la Președinte, care îl poate semna, respinge sau, dacă nu face nimic zece zile cât timp Congresul e în sesiune, îl poate lăsa să devină lege. Congresul poate trece peste veto, dar numai cu două treimi în fiecare cameră.",
    history: "The Presentment Clause is the engine of federal lawmaking and a load-bearing pillar of the separation of powers: no bill becomes law without both chambers agreeing and the President either signing or being overridden. Requiring revenue bills to originate in the House echoed the English principle that the power to tax belongs to the body closest to the people. The \"pocket veto,\" letting a bill die unsigned when Congress adjourns, comes from the clause's final sentence.",
    historyRo: "Clauza Prezentării e motorul legiferării federale și un pilon de rezistență al separării puterilor: niciun proiect nu devine lege fără ca ambele camere să fie de acord și Președintele fie să semneze, fie să fie depășit. Cerința ca proiectele de venituri să înceapă în Cameră reflecta principiul englez că puterea de a impozita aparține corpului cel mai apropiat de popor. „Vetoul de buzunar”, lăsarea unui proiect să moară nesemnat când Congresul se suspendă, vine din ultima frază a clauzei.",
    cases: [
      { name: "INS v. Chadha", year: "1983", note: "Any action that changes legal rights must run through bicameralism and presentment, no shortcuts.", noteRo: "Orice acțiune care schimbă drepturi legale trebuie să treacă prin bicameralism și prezentare, fără scurtături." },
      { name: "Clinton v. City of New York", year: "1998", note: "The President cannot cancel parts of a signed law; presentment is all-or-nothing.", noteRo: "Președintele nu poate anula părți dintr-o lege semnată; prezentarea e totul sau nimic." },
    ],
    examples: "Presidential vetoes and the drama of override votes, the ten-day \"pocket veto\" at the end of a session, and the requirement that the House and Senate reconcile their versions of a bill before it can become law all run on this clause. Every statute on the books passed through the exact process this section describes.",
    examplesRo: "Vetourile prezidențiale și drama voturilor de trecere peste veto, „vetoul de buzunar” de zece zile la finalul unei sesiuni și cerința ca Camera și Senatul să-și reconcilieze versiunile unui proiect înainte de a deveni lege funcționează toate pe această clauză. Fiecare lege din vigoare a trecut prin exact procesul descris de această secțiune.",
    debates: "The line-item veto, letting a president strike individual wasteful items from a spending bill, is popular with budget reformers but was ruled unconstitutional under this section, so the fight has shifted to proposals for a constitutional amendment. A related modern tension is over massive omnibus bills and continuing resolutions, thousands of pages voted on at once, which critics say twist the deliberate, bill-by-bill process the Framers imagined.",
    debatesRo: "Vetoul pe articole, care i-ar permite unui președinte să taie articole risipitoare individuale dintr-un proiect de cheltuieli, e popular la reformatorii bugetari, dar a fost declarat neconstituțional sub această secțiune, așa că lupta s-a mutat spre propuneri de amendament constituțional. O tensiune modernă înrudită privește proiectele-omnibus masive și rezoluțiile de continuare, mii de pagini votate deodată, despre care criticii spun că denaturează procesul deliberativ, proiect cu proiect, imaginat de Fondatori.",
  },
  "art1-s8": {
    plain: "This is the master list of what Congress may actually do. It can tax and spend for the common defense and general welfare, borrow money, regulate commerce with other nations and among the states, set uniform rules for citizenship and bankruptcy, coin money, run the post office, grant patents and copyrights, create the lower federal courts, declare war and raise armies and a navy, govern the national capital, and, at the very end, make any law \"necessary and proper\" to carry all of those powers out.",
    plainRo: "Aceasta e lista principală a ceea ce poate face de fapt Congresul. Poate impozita și cheltui pentru apărarea comună și bunăstarea generală, împrumuta bani, reglementa comerțul cu alte națiuni și între state, stabili reguli uniforme de cetățenie și faliment, bate monedă, conduce poșta, acorda patente și drepturi de autor, crea instanțele federale inferioare, declara război și ridica armate și o marină, guverna capitala națională și, chiar la final, face orice lege „necesară și potrivită” pentru a duce la capăt toate aceste puteri.",
    history: "Section 8 is the source of nearly all federal power, and its last clause, the Necessary and Proper Clause, is the hinge on which the reach of the whole government turns. Alexander Hamilton argued it authorized a national bank though banks are nowhere mentioned, and Chief Justice Marshall enshrined that broad reading in McCulloch v. Maryland. Together with the Commerce Clause, it let a government of enumerated powers stretch to govern a continental, industrial, and now digital nation the Framers could never have pictured.",
    historyRo: "Secțiunea 8 e sursa aproape a întregii puteri federale, iar ultima ei clauză, Clauza Necesar și Potrivit, e balamaua pe care se rotește întinderea întregului guvern. Alexander Hamilton a argumentat că autoriza o bancă națională deși băncile nu sunt menționate nicăieri, iar judecătorul-șef Marshall a consacrat acea interpretare largă în McCulloch v. Maryland. Împreună cu Clauza Comerțului, a permis unui guvern cu puteri enumerate să se întindă pentru a guverna o națiune continentală, industrială și acum digitală pe care Fondatorii nu ar fi putut-o imagina.",
    cases: [
      { name: "McCulloch v. Maryland", year: "1819", note: "\"Necessary and proper\" means convenient and useful, not strictly indispensable; Congress could charter a national bank.", noteRo: "„Necesar și potrivit” înseamnă convenabil și util, nu strict indispensabil; Congresul putea înființa o bancă națională." },
      { name: "Gibbons v. Ogden", year: "1824", note: "Gave the Commerce Clause a broad early reading, covering navigation and interstate trade.", noteRo: "A dat Clauzei Comerțului o interpretare timpurie largă, acoperind navigația și comerțul interstatal." },
      { name: "Wickard v. Filburn", year: "1942", note: "Congress may regulate even wheat a farmer grows for his own use, because in the aggregate it affects interstate commerce.", noteRo: "Congresul poate reglementa chiar grâul pe care un fermier îl cultivă pentru consum propriu, fiindcă în ansamblu afectează comerțul interstatal." },
      { name: "United States v. Lopez", year: "1995", note: "A first modern limit: carrying a gun near a school is not economic activity Congress can reach through commerce.", noteRo: "O primă limită modernă: purtarea unei arme lângă o școală nu e activitate economică pe care Congresul o poate atinge prin comerț." },
      { name: "NFIB v. Sebelius", year: "2012", note: "The health-insurance mandate exceeded the Commerce power but survived as a tax.", noteRo: "Mandatul de asigurare de sănătate depășea puterea de comerț, dar a supraviețuit ca impozit." },
    ],
    examples: "Federal civil-rights laws, environmental and drug laws, Social Security, Medicare, the interstate highway system, the patent and copyright regime, and the armed forces all rest on the taxing, spending, and commerce powers listed here. When people ask \"where does Congress get the authority to do that?\", the answer is almost always somewhere in Section 8.",
    examplesRo: "Legile federale privind drepturile civile, legile de mediu și cele privind drogurile, Social Security, Medicare, sistemul de autostrăzi interstatale, regimul patentelor și drepturilor de autor și forțele armate se sprijină toate pe puterile de impozitare, cheltuire și comerț enumerate aici. Când oamenii întreabă „de unde ia Congresul autoritatea să facă asta?”, răspunsul e aproape întotdeauna undeva în Secțiunea 8.",
    debates: "How far the Commerce and Spending powers reach is the central, never-settled question of American constitutional law. A broad reading powered the New Deal, the Civil Rights Act, and the modern regulatory state; but Lopez, Morrison, and NFIB show a Court willing again to police an outer boundary, insisting there are things too local or too non-economic for Congress to touch. The same tension runs through fights over healthcare, guns, drugs, and federal spending conditions attached to state grants.",
    debatesRo: "Cât de departe ajung puterile de comerț și cheltuieli e întrebarea centrală, niciodată soluționată, a dreptului constituțional american. O interpretare largă a alimentat New Deal, Legea Drepturilor Civile și statul de reglementare modern; dar Lopez, Morrison și NFIB arată o Curte dispusă din nou să păzească o graniță exterioară, insistând că există lucruri prea locale sau prea non-economice pentru ca Congresul să le atingă. Aceeași tensiune străbate luptele despre sănătate, arme, droguri și condițiile de cheltuire federală atașate granturilor statale.",
  },
  "art1-s9": {
    plain: "Even Congress has hard limits. It cannot suspend habeas corpus (the right to challenge unlawful imprisonment) except during rebellion or invasion, cannot pass bills of attainder (laws punishing named people without trial) or ex post facto laws (making an act a crime after the fact), cannot spend a dollar from the Treasury without an appropriation, and its officials cannot accept gifts or titles from foreign governments.",
    plainRo: "Chiar și Congresul are limite ferme. Nu poate suspenda habeas corpus (dreptul de a contesta întemnițarea ilegală) decât în timpul rebeliunii sau invaziei, nu poate adopta bills of attainder (legi care pedepsesc persoane numite fără proces) sau legi ex post facto (transformarea unei fapte în infracțiune după ce a fost comisă), nu poate cheltui un dolar din Trezorerie fără o alocare, iar oficialii săi nu pot accepta daruri sau titluri de la guverne străine.",
    history: "These are ancient guarantees of liberty, written into the body of the Constitution before the Bill of Rights even existed. Habeas corpus, the \"Great Writ\" of English law, is the right that forces the government to justify holding a person; bills of attainder and ex post facto laws were favorite tools of tyranny the Framers wanted permanently banned. The Emoluments Clause was meant to keep American officials free of foreign bribery, a fresh worry for a young, weak republic surrounded by powerful monarchies.",
    historyRo: "Acestea sunt garanții străvechi ale libertății, înscrise în corpul Constituției înainte ca Declarația Drepturilor să existe. Habeas corpus, „Marele Ordin” al dreptului englez, e dreptul care obligă guvernul să justifice reținerea unei persoane; bills of attainder și legile ex post facto erau instrumente favorite ale tiraniei pe care Fondatorii voiau să le interzică permanent. Clauza Emolumentelor trebuia să țină oficialii americani liberi de mituirea străină, o grijă proaspătă pentru o republică tânără și slabă înconjurată de monarhii puternice.",
    cases: [
      { name: "Ex parte Milligan", year: "1866", note: "Civilians cannot be tried by military tribunals where the civil courts are open, even in wartime.", noteRo: "Civilii nu pot fi judecați de tribunale militare unde instanțele civile funcționează, chiar în război." },
      { name: "Ex parte Merryman", year: "1861", note: "Challenged Lincoln's Civil War suspension of habeas corpus, framing a lasting dispute over who may suspend it.", noteRo: "A contestat suspendarea habeas corpus de către Lincoln în Războiul Civil, conturând o dispută durabilă despre cine îl poate suspenda." },
      { name: "Boumediene v. Bush", year: "2008", note: "Guantánamo detainees keep the habeas corpus right; Congress cannot simply strip it away.", noteRo: "Deținuții de la Guantánamo păstrează dreptul la habeas corpus; Congresul nu îl poate elimina pur și simplu." },
    ],
    examples: "Lincoln's suspension of habeas corpus during the Civil War, the constitutional ban on retroactive criminal laws, the requirement that all federal spending be appropriated by law, and the modern lawsuits over whether a president's businesses violate the Emoluments Clause all live in this section. Government shutdowns happen precisely because no money may leave the Treasury without a fresh appropriation.",
    examplesRo: "Suspendarea habeas corpus de către Lincoln în Războiul Civil, interdicția constituțională a legilor penale retroactive, cerința ca toate cheltuielile federale să fie alocate prin lege și procesele moderne despre dacă afacerile unui președinte încalcă Clauza Emolumentelor trăiesc toate în această secțiune. Blocajele guvernamentale se întâmplă tocmai fiindcă niciun ban nu poate ieși din Trezorerie fără o alocare nouă.",
    debates: "When habeas corpus may be suspended, and crucially whether only Congress or also the President may do it, has been argued since Lincoln acted unilaterally in 1861, and it returned with force in the post-9/11 detention cases. The Emoluments Clauses, nearly dormant for two centuries, became the center of high-profile litigation over a president's private hotels and foreign payments, testing how far this old anti-corruption rule reaches into modern business.",
    debatesRo: "Când poate fi suspendat habeas corpus și, esențial, dacă doar Congresul sau și Președintele o poate face, se dezbate de când Lincoln a acționat unilateral în 1861, și a revenit cu forță în cazurile de detenție de după 11 septembrie. Clauzele Emolumentelor, aproape inactive două secole, au devenit centrul unor litigii de mare profil despre hotelurile private ale unui președinte și plățile străine, testând cât de departe ajunge această veche regulă anticorupție în afacerile moderne.",
  },
  "art1-s10": {
    plain: "The states are forbidden from acting like independent countries. They cannot make treaties, coin their own money, or tax imports and exports without Congress; they cannot keep standing armies or warships in peacetime or go to war unless actually invaded; and they cannot pass laws that break existing contracts or hand out titles of nobility.",
    plainRo: "Statelor le e interzis să se poarte ca țări independente. Nu pot încheia tratate, bate propria monedă sau impozita importurile și exporturile fără Congres; nu pot ține armate permanente sau nave de război pe timp de pace și nu pot merge la război decât dacă sunt efectiv invadate; și nu pot adopta legi care rup contracte existente sau acorda titluri de noblețe.",
    history: "These bans fix the great failure of the Articles of Confederation, under which states waged trade wars against one another, printed floods of worthless paper money, and passed debtor-relief laws that wrecked commerce. Concentrating foreign affairs, war, and a single hard currency in the national government is what turned thirteen quarreling states into one functioning economy. The Contracts Clause in particular reflected the Framers' alarm at state legislatures dissolving debts on a whim.",
    historyRo: "Aceste interdicții repară marele eșec al Articolelor Confederației, sub care statele purtau războaie comerciale unul împotriva altuia, tipăreau puhoaie de bani de hârtie fără valoare și adoptau legi de ajutorare a debitorilor care distrugeau comerțul. Concentrarea afacerilor externe, a războiului și a unei singure monede solide în guvernul național e ceea ce a transformat treisprezece state certărețe într-o singură economie funcțională. Clauza Contractelor în special reflecta alarma Fondatorilor față de legislaturile statale care dizolvau datorii după bunul plac.",
    cases: [
      { name: "Fletcher v. Peck", year: "1810", note: "The first time the Court struck down a state law, using the Contracts Clause.", noteRo: "Prima dată când Curtea a anulat o lege statală, folosind Clauza Contractelor." },
      { name: "Dartmouth College v. Woodward", year: "1819", note: "A corporate charter is a contract a state cannot unilaterally revoke.", noteRo: "Un statut corporativ e un contract pe care un stat nu îl poate revoca unilateral." },
      { name: "Home Building & Loan Ass'n v. Blaisdell", year: "1934", note: "In a genuine emergency, states have some room to adjust contract remedies.", noteRo: "Într-o urgență reală, statele au ceva spațiu să ajusteze remediile contractuale." },
    ],
    examples: "Interstate compacts, like the agreement governing the Port Authority of New York and New Jersey, need congressional consent under this section, and disputes over state tariffs, currency experiments, and contract-impairing laws are judged here. It is why a state cannot sign its own trade treaty or coin its own dollar.",
    examplesRo: "Pactele interstatale, precum acordul care guvernează Autoritatea Portuară din New York și New Jersey, au nevoie de consimțământul Congresului sub această secțiune, iar disputele despre tarifele statale, experimentele monetare și legile care afectează contractele sunt judecate aici. De aceea un stat nu poate semna propriul tratat comercial sau bate propriul dolar.",
    debates: "The Contracts Clause was once a powerful brake on state economic regulation, and how strong it should be against modern debtor-relief, rent-control, and pension-adjustment laws is still argued whenever a state alters obligations in a crisis. A newer edge is how far states may go on the world stage, striking climate or trade arrangements with foreign governments, before they cross the line into the treaty-making this section reserves to the nation.",
    debatesRo: "Clauza Contractelor a fost cândva o frână puternică asupra reglementării economice statale, iar cât de puternică ar trebui să fie față de legile moderne de ajutorare a debitorilor, de control al chiriilor și de ajustare a pensiilor e încă disputat ori de câte ori un stat modifică obligații într-o criză. O margine mai nouă e cât de departe pot merge statele pe scena mondială, încheind aranjamente climatice sau comerciale cu guverne străine, înainte de a trece linia în încheierea de tratate pe care această secțiune o rezervă națiunii.",
  },

  // ── Article II ───────────────────────────────────────────────────────────────
  "art2-s1": {
    plain: "A single President holds the executive power for a four-year term. The President is chosen not directly by the voters but by electors that each state appoints, the Electoral College, with each state getting as many electors as it has members of Congress. To qualify you must be a natural-born citizen, at least 35, and a U.S. resident for fourteen years, and before taking office you swear a fixed oath to \"preserve, protect and defend the Constitution.\"",
    plainRo: "Un singur Președinte deține puterea executivă pentru un mandat de patru ani. Președintele e ales nu direct de alegători, ci de electori pe care fiecare stat îi numește, Colegiul Electoral, fiecare stat primind atâția electori câți membri ai Congresului are. Pentru a te califica trebuie să fii cetățean născut în țară, de cel puțin 35 de ani și rezident al SUA de paisprezece ani, iar înainte de a prelua funcția depui un jurământ fix de a „păstra, proteja și apăra Constituția”.",
    history: "The Electoral College was a compromise between those who wanted Congress to pick the President and those who wanted a direct popular vote; the Framers feared both a legislature-dependent executive and a purely popular demagogue. Vesting \"the executive power\" in one person, rather than a council, was itself controversial, chosen so that responsibility, and blame, would always be clear. The original two-vote elector system broke down almost immediately and was rewritten by the 12th Amendment in 1804.",
    historyRo: "Colegiul Electoral a fost un compromis între cei care voiau ca Congresul să aleagă Președintele și cei care voiau un vot popular direct; Fondatorii se temeau atât de un executiv dependent de legislativ, cât și de un demagog pur popular. Învestirea „puterii executive” într-o singură persoană, nu într-un consiliu, a fost ea însăși controversată, aleasă pentru ca responsabilitatea, și vina, să fie mereu clare. Sistemul original al electorilor cu două voturi s-a prăbușit aproape imediat și a fost rescris de Amendamentul 12 în 1804.",
    cases: [
      { name: "Bush v. Gore", year: "2000", note: "Halted a Florida recount, effectively deciding the presidency on Equal Protection grounds.", noteRo: "A oprit o renumărare din Florida, decizând efectiv președinția pe temeiul Egalei Protecții." },
      { name: "Chiafalo v. Washington", year: "2020", note: "States may legally bind their electors to the popular vote and punish \"faithless\" electors.", noteRo: "Statele își pot obliga legal electorii să respecte votul popular și pot pedepsi electorii „necredincioși”." },
    ],
    amendments: ["amend-12", "amend-22", "amend-23", "amend-25"],
    examples: "Every four years the Electoral College, not the nationwide popular vote, formally elects the President, and twice this century, in 2000 and 2016, the candidate who lost the popular vote won the presidency. The oath in this section is the one every incoming President recites at the inauguration.",
    examplesRo: "La fiecare patru ani Colegiul Electoral, nu votul popular la nivel național, alege formal Președintele, iar de două ori în acest secol, în 2000 și 2016, candidatul care a pierdut votul popular a câștigat președinția. Jurământul din această secțiune e cel pe care fiecare Președinte care intră în funcție îl recită la învestitură.",
    debates: "Whether to abolish the Electoral College for a national popular vote is one of the longest-running structural debates in American politics; reformers call it undemocratic and distorting, while defenders say it protects smaller states and forces candidates to build broad geographic coalitions. The \"natural born Citizen\" requirement also draws recurring argument over exactly who qualifies, from candidates born abroad to children of citizens overseas.",
    debatesRo: "Dacă să se desființeze Colegiul Electoral în favoarea votului popular național e una dintre cele mai vechi dezbateri structurale din politica americană; reformatorii îl numesc nedemocratic și distorsionant, în timp ce apărătorii spun că protejează statele mai mici și forțează candidații să construiască coaliții geografice largi. Cerința de „cetățean născut în țară” atrage de asemenea argumente recurente despre cine anume se califică, de la candidați născuți în străinătate la copii ai cetățenilor din afara țării.",
  },
  "art2-s2": {
    plain: "This section lists the President's powers. He is Commander in Chief of the armed forces, can grant pardons and reprieves for federal crimes, makes treaties (which need two-thirds of the Senate to ratify), and nominates ambassadors, federal judges, Supreme Court justices, and top officials, all of whom need Senate confirmation. He can also fill vacancies temporarily while the Senate is in recess.",
    plainRo: "Această secțiune enumeră puterile Președintelui. E Comandant Suprem al forțelor armate, poate acorda grațieri și amânări pentru infracțiuni federale, încheie tratate (care au nevoie de două treimi din Senat pentru ratificare) și nominalizează ambasadori, judecători federali, judecători ai Curții Supreme și înalți funcționari, toți având nevoie de confirmarea Senatului. Poate de asemenea ocupa vacanțe temporar cât timp Senatul e în vacanță.",
    history: "The Appointments and Treaty Clauses are the Senate's principal leashes on the President, forcing him to share his two greatest powers, staffing the government and conducting diplomacy, with the legislature. The pardon power, by contrast, is nearly absolute for federal offenses, descending directly from the royal prerogative of mercy, checked only by the ban on pardoning impeachment. Making the President \"Commander in Chief\" put a civilian permanently atop the military, a deliberate rejection of military rule.",
    historyRo: "Clauzele Numirilor și Tratatelor sunt principalele lese ale Senatului asupra Președintelui, obligându-l să împartă cele mai mari două puteri ale sale, numirea guvernului și conducerea diplomației, cu legislativul. Puterea de grațiere, în schimb, e aproape absolută pentru infracțiuni federale, coborând direct din prerogativa regală a milei, limitată doar de interdicția de a grația destituirea. Numirea Președintelui „Comandant Suprem” a pus un civil permanent în fruntea armatei, o respingere deliberată a guvernării militare.",
    cases: [
      { name: "NLRB v. Noel Canning", year: "2014", note: "Limited the recess-appointment power; the Senate itself decides when it is truly in recess.", noteRo: "A limitat puterea numirilor în vacanță; Senatul însuși decide când e cu adevărat în vacanță." },
      { name: "Youngstown Sheet & Tube v. Sawyer", year: "1952", note: "The commander-in-chief power did not let the President seize private steel mills during the Korean War.", noteRo: "Puterea de comandant suprem nu i-a permis Președintelui să confiște oțelării private în timpul Războiului din Coreea." },
      { name: "Trump v. United States", year: "2024", note: "Recognized broad presidential immunity for official acts within core executive powers.", noteRo: "A recunoscut o imunitate prezidențială largă pentru actele oficiale din puterile executive de bază." },
    ],
    examples: "Supreme Court and federal-judge confirmations, treaty ratifications, and high-profile pardons, from Ford pardoning Nixon to controversial last-day clemencies, all run through the powers listed here. Recess appointments let presidents temporarily install officials the Senate refuses to confirm.",
    examplesRo: "Confirmările la Curtea Supremă și ale judecătorilor federali, ratificările de tratate și grațierile de mare profil, de la Ford grațiindu-l pe Nixon la clemențe controversate din ultima zi, trec toate prin puterile enumerate aici. Numirile în vacanță le permit președinților să instaleze temporar funcționari pe care Senatul refuză să-i confirme.",
    debates: "How far the commander-in-chief power lets a President wage war without a congressional declaration is a decades-old dispute that flares with every overseas deployment and the War Powers Resolution. The pardon power raises its own hard questions, whether a president may pardon his own associates, or even himself, and after Trump v. United States, the scope of presidential immunity for official acts has become one of the most contested issues in the separation of powers.",
    debatesRo: "Cât de departe îi permite puterea de comandant suprem unui Președinte să poarte război fără o declarație a Congresului e o dispută veche de decenii care izbucnește la fiecare desfășurare peste hotare și la Rezoluția Puterilor de Război. Puterea de grațiere ridică propriile întrebări grele, dacă un președinte își poate grația proprii asociați, sau chiar pe sine, iar după Trump v. United States, întinderea imunității prezidențiale pentru actele oficiale a devenit una dintre cele mai disputate chestiuni ale separării puterilor.",
  },
  "art2-s3": {
    plain: "This section lists the President's duties. He must report to Congress on the state of the union, may recommend legislation and call Congress into special session, receives foreign ambassadors, and, above all, must \"take Care that the Laws be faithfully executed.\" That last phrase makes the President the nation's chief law-enforcer, bound to carry out the laws Congress passes.",
    plainRo: "Această secțiune enumeră îndatoririle Președintelui. Trebuie să raporteze Congresului despre starea uniunii, poate recomanda legi și convoca Congresul în sesiune specială, primește ambasadori străini și, mai presus de toate, trebuie să „vegheze ca legile să fie fidel executate”. Ultima sintagmă face din Președinte principalul executor al legii națiunii, obligat să aplice legile pe care le adoptă Congresul.",
    history: "The Take Care Clause is the constitutional heart of the President's job: he does not make the laws or judge them, he executes them, and he must do so faithfully even for laws he opposes. The seemingly modest duty to \"receive Ambassadors\" quietly grew into the President's now-dominant power to recognize foreign governments and set the nation's diplomatic posture. The State of the Union, once a written message, became the great annual set-piece of American politics.",
    historyRo: "Clauza Vegherii e inima constituțională a slujbei Președintelui: el nu face legile și nu le judecă, le execută, și trebuie să o facă fidel chiar și pentru legile la care se opune. Datoria aparent modestă de a „primi ambasadori” a crescut discret în puterea acum dominantă a Președintelui de a recunoaște guverne străine și de a stabili poziția diplomatică a națiunii. Starea Uniunii, cândva un mesaj scris, a devenit marele moment anual al politicii americane.",
    cases: [
      { name: "Youngstown Sheet & Tube v. Sawyer", year: "1952", note: "The President cannot seize private industry to enforce his policy; executive power is weakest against Congress's will.", noteRo: "Președintele nu poate confisca industria privată pentru a-și impune politica; puterea executivă e cea mai slabă împotriva voinței Congresului." },
      { name: "United States v. Texas", year: "2023", note: "Addressed how far states can sue to force the executive to enforce immigration law more aggressively.", noteRo: "A abordat cât de departe pot merge statele să dea în judecată pentru a forța executivul să aplice legea imigrației mai agresiv." },
    ],
    examples: "The annual State of the Union address, presidential recognition of new governments, and bitter fights over whether an administration is enforcing, or refusing to enforce, immigration, drug, or environmental laws all rest on this section. \"Prosecutorial discretion\" in immigration is a direct descendant of the Take Care Clause.",
    examplesRo: "Discursul anual despre Starea Uniunii, recunoașterea prezidențială a noilor guverne și luptele aprige despre dacă o administrație aplică, sau refuză să aplice, legile de imigrație, droguri sau mediu se sprijină toate pe această secțiune. „Discreția de urmărire penală” în imigrație e un descendent direct al Clauzei Vegherii.",
    debates: "Prosecutorial discretion is the core Take Care controversy: how far may a President go in declining to enforce laws he disagrees with, deferring deportations, deprioritizing drug prosecutions, before he is effectively suspending the law, a power the Constitution denies him. The flip side, whether states or Congress can force a reluctant executive to enforce a law more vigorously, is now reaching the Supreme Court.",
    debatesRo: "Discreția de urmărire penală e controversa centrală a Vegherii: cât de departe poate merge un Președinte refuzând să aplice legi cu care nu e de acord, amânând deportări, depriorizând urmăririle pentru droguri, înainte de a suspenda efectiv legea, o putere pe care Constituția i-o refuză. Reversul, dacă statele sau Congresul pot forța un executiv reticent să aplice o lege mai viguros, ajunge acum la Curtea Supremă.",
  },
  "art2-s4": {
    plain: "The President, Vice President, and all civil federal officers can be removed from office if they are impeached (charged) by the House and convicted by the Senate for \"Treason, Bribery, or other high Crimes and Misdemeanors.\" Impeachment is the Constitution's ultimate check on a corrupt or dangerous official.",
    plainRo: "Președintele, Vicepreședintele și toți funcționarii civili federali pot fi înlăturați din funcție dacă sunt puși sub acuzare de Cameră și condamnați de Senat pentru „Trădare, Mituire sau alte Infracțiuni și Delicte grave”. Punerea sub acuzare e controlul suprem al Constituției asupra unui oficial corupt sau periculos.",
    history: "\"High Crimes and Misdemeanors\" is borrowed from centuries of English parliamentary practice, where it meant serious abuses of public trust, not only ordinary crimes, and the Framers left it deliberately broad to cover conduct no statute might name. They rejected \"maladministration\" as too vague and too easy a tool for removing a president over mere policy disagreement. Impeachment was meant to be a grave, rare remedy, aimed at protecting the republic, not settling political scores.",
    historyRo: "„Infracțiuni și delicte grave” e împrumutat din secole de practică parlamentară engleză, unde însemna abuzuri grave de încredere publică, nu doar infracțiuni obișnuite, iar Fondatorii l-au lăsat deliberat larg pentru a acoperi conduite pe care nicio lege nu le-ar numi. Au respins „administrarea proastă” ca prea vagă și prea ușor instrument de înlăturare a unui președinte pentru un simplu dezacord de politică. Punerea sub acuzare trebuia să fie un remediu grav și rar, menit să protejeze republica, nu să regleze conturi politice.",
    cases: [
      { name: "Nixon v. United States", year: "1993", note: "Judge Walter Nixon's case: courts will not review how the Senate structures an impeachment trial.", noteRo: "Cazul judecătorului Walter Nixon: instanțele nu revizuiesc modul în care Senatul structurează un proces de destituire." },
    ],
    examples: "Three presidents have been impeached by the House, Andrew Johnson, Bill Clinton, and Donald Trump (twice), and this section also reaches judges and cabinet officers, several of whom have been impeached and some removed. It connects directly to the House's sole power to impeach and the Senate's sole power to try.",
    examplesRo: "Trei președinți au fost puși sub acuzare de Cameră, Andrew Johnson, Bill Clinton și Donald Trump (de două ori), iar această secțiune ajunge și la judecători și miniștri, dintre care câțiva au fost puși sub acuzare și unii înlăturați. Se leagă direct de puterea exclusivă a Camerei de a acuza și a Senatului de a judeca.",
    debates: "The deepest argument is whether \"high Crimes and Misdemeanors\" requires an actual crime or covers broader abuses of power and betrayals of the public trust, and, closely tied to that, whether impeachment is fundamentally a legal judgment or an inescapably political one. Because conviction needs two-thirds of the Senate, it has proven nearly impossible to remove a president whose party holds even a third of that chamber, raising the question of whether the remedy still works.",
    debatesRo: "Argumentul cel mai profund e dacă „infracțiuni și delicte grave” cere o infracțiune reală sau acoperă abuzuri mai largi de putere și trădări ale încrederii publice, și, strâns legat de asta, dacă punerea sub acuzare e fundamental o judecată juridică sau una inevitabil politică. Fiindcă condamnarea are nevoie de două treimi din Senat, s-a dovedit aproape imposibil de înlăturat un președinte al cărui partid deține chiar și o treime din acea cameră, ridicând întrebarea dacă remediul mai funcționează.",
  },

  // ── Article III ──────────────────────────────────────────────────────────────
  "art3-s1": {
    plain: "There is exactly one court the Constitution creates, the Supreme Court, and Congress may build whatever lower federal courts it wants beneath it. Federal judges serve \"during good Behaviour,\" which has come to mean for life, and their salaries cannot be reduced while they serve. Both protections exist for one reason: to make judges independent and fearless.",
    plainRo: "Există exact o singură instanță pe care o creează Constituția, Curtea Supremă, iar Congresul poate construi sub ea orice instanțe federale inferioare dorește. Judecătorii federali servesc „cât timp se poartă bine”, ceea ce a ajuns să însemne pe viață, iar salariile lor nu pot fi reduse cât timp servesc. Ambele protecții există dintr-un singur motiv: să facă judecătorii independenți și neînfricați.",
    history: "Life tenure and protected pay were the Framers' answer to a hard question: how do you make a judge willing to rule against the president who appointed him or the Congress that pays him? Hamilton called the judiciary the \"least dangerous branch,\" holding neither sword nor purse, and thought its independence had to be armored precisely because it was otherwise so weak. The section leaves the size and shape of the federal court system almost entirely to Congress, which is why the number of justices and lower courts has changed over time.",
    historyRo: "Mandatul pe viață și salariul protejat au fost răspunsul Fondatorilor la o întrebare grea: cum faci un judecător dispus să decidă împotriva președintelui care l-a numit sau a Congresului care îl plătește? Hamilton a numit judecătorescul „ramura cea mai puțin periculoasă”, neținând nici sabie, nici pungă, și a crezut că independența ei trebuia blindată tocmai fiindcă era altfel atât de slabă. Secțiunea lasă mărimea și forma sistemului judiciar federal aproape în întregime Congresului, motiv pentru care numărul judecătorilor și al instanțelor inferioare s-a schimbat în timp.",
    cases: [
      { name: "Marbury v. Madison", year: "1803", note: "Established judicial review, the Court's power to strike down laws that violate the Constitution.", noteRo: "A stabilit controlul judiciar, puterea Curții de a anula legile care încalcă Constituția." },
      { name: "Stern v. Marshall", year: "2011", note: "Limited how much judicial power Congress may hand to non-life-tenured bankruptcy judges.", noteRo: "A limitat cât din puterea judecătorească poate ceda Congresul judecătorilor de faliment fără mandat pe viață." },
    ],
    examples: "The entire federal court system, from district courts to circuit courts of appeals to the Supreme Court, is built on this one section, and every confirmation battle over a lifetime judicial appointment is a fight over the independence it protects. Because judges cannot be fired for their rulings, they can, and do, decide against the most powerful people in the country.",
    examplesRo: "Întregul sistem judiciar federal, de la instanțele de district la curțile de apel de circuit și Curtea Supremă, e construit pe această singură secțiune, iar fiecare bătălie de confirmare pentru o numire judiciară pe viață e o luptă pentru independența pe care o protejează. Fiindcă judecătorii nu pot fi concediați pentru deciziile lor, ei pot, și chiar decid, împotriva celor mai puternici oameni din țară.",
    debates: "Whether lifetime tenure still serves the country is now openly debated: supporters say it is the guarantee of an independent judiciary, while critics point to justices serving into their eighties and strategic retirements, and propose fixed 18-year terms for the Supreme Court. Proposals to expand or shrink the number of justices, \"court-packing,\" also test this section, since the Constitution fixes neither the Court's size nor the shape of the courts below it.",
    debatesRo: "Dacă mandatul pe viață mai servește țara e acum dezbătut deschis: susținătorii spun că e garanția unui judecătoresc independent, în timp ce criticii arată judecători care servesc până la optzeci de ani și pensionări strategice și propun mandate fixe de 18 ani pentru Curtea Supremă. Propunerile de a mări sau micșora numărul judecătorilor, „umplerea instanței”, testează de asemenea această secțiune, fiindcă Constituția nu fixează nici mărimea Curții, nici forma instanțelor de sub ea.",
  },
  "art3-s2": {
    plain: "This section defines what federal courts are allowed to hear: cases arising under the Constitution and federal law, disputes between states, and cases between citizens of different states, among others. A few kinds of cases go straight to the Supreme Court; the rest reach it only on appeal, under rules Congress sets. And it guarantees that all federal crimes must be tried by a jury in the state where they happened.",
    plainRo: "Această secțiune definește ce au voie să judece instanțele federale: cazuri ce decurg din Constituție și legea federală, dispute între state și cazuri între cetățeni ai unor state diferite, printre altele. Câteva tipuri de cazuri merg direct la Curtea Supremă; restul ajung la ea doar în apel, sub reguli stabilite de Congres. Și garantează că toate infracțiunile federale trebuie judecate de un juriu în statul unde s-au întâmplat.",
    history: "This section marks the outer boundary of federal judicial power, everything beyond it belongs to the state courts. The phrase \"arising under this Constitution,\" combined with Marbury's judicial review, is what makes the Supreme Court the final interpreter of the Constitution's meaning. Congress's control over the Court's appellate jurisdiction is a rarely used but potent check, letting the legislature, in theory, strip certain cases from the Court's reach.",
    historyRo: "Această secțiune marchează granița exterioară a puterii judecătorești federale, tot ce e dincolo de ea aparține instanțelor statale. Sintagma „ce decurge din această Constituție”, combinată cu controlul judiciar din Marbury, e ceea ce face din Curtea Supremă interpretul final al sensului Constituției. Controlul Congresului asupra competenței de apel a Curții e un control rar folosit dar puternic, permițând legislativului, în teorie, să scoată anumite cazuri din raza Curții.",
    cases: [
      { name: "Marbury v. Madison", year: "1803", note: "Read this section to establish judicial review over acts of Congress.", noteRo: "A interpretat această secțiune pentru a stabili controlul judiciar asupra actelor Congresului." },
      { name: "Chisholm v. Georgia", year: "1793", note: "Let a citizen sue a state, an outcome so unpopular it produced the 11th Amendment.", noteRo: "A permis unui cetățean să dea în judecată un stat, un rezultat atât de nepopular încât a produs Amendamentul 11." },
      { name: "Ex parte McCardle", year: "1869", note: "Congress may strip the Court of jurisdiction over a class of cases, even mid-appeal.", noteRo: "Congresul poate scoate din competența Curții o categorie de cazuri, chiar în mijlocul apelului." },
    ],
    amendments: ["amend-11", "amend-6", "amend-7"],
    examples: "The criminal jury guarantee here, expanded by the 6th and 7th Amendments, underlies the American jury system, and \"diversity jurisdiction,\" letting citizens of different states sue in federal court, keeps countless business and injury cases in federal hands. Every case that reaches the Supreme Court arrives through the jurisdictional map this section draws.",
    examplesRo: "Garanția juriului penal de aici, extinsă de Amendamentele 6 și 7, stă la baza sistemului american de jurați, iar „competența de diversitate”, care le permite cetățenilor unor state diferite să se judece în instanța federală, ține nenumărate cazuri de afaceri și vătămări în mâini federale. Fiecare caz care ajunge la Curtea Supremă sosește prin harta de competență pe care o trasează această secțiune.",
    debates: "State sovereign immunity, how far the 11th Amendment shields states from being sued in federal court, is a heavily litigated federalism puzzle rooted directly in this section. Separately, \"jurisdiction stripping,\" the idea that Congress could bar the federal courts from hearing cases on hot-button issues like abortion or school prayer, resurfaces whenever a political majority is frustrated with the judiciary, testing how far the legislature may go in disarming the courts.",
    debatesRo: "Imunitatea suverană a statelor, cât de mult le protejează Amendamentul 11 de a fi date în judecată în instanța federală, e o enigmă de federalism intens litigată, înrădăcinată direct în această secțiune. Separat, „scoaterea din competență”, ideea că Congresul ar putea interzice instanțelor federale să judece cazuri pe teme fierbinți precum avortul sau rugăciunea în școli, reapare ori de câte ori o majoritate politică e frustrată de judecătoresc, testând cât de departe poate merge legislativul în dezarmarea instanțelor.",
  },
  "art3-s3": {
    plain: "Treason is the only crime the Constitution itself defines, and it is defined narrowly: making war against the United States, or giving its enemies \"aid and comfort.\" To convict, the government needs either two witnesses to the same open act or a confession in court. Punishment can be severe, but it cannot be extended to punish the traitor's innocent family.",
    plainRo: "Trădarea e singura infracțiune pe care Constituția însăși o definește, și e definită restrâns: purtarea de război împotriva Statelor Unite sau oferirea „ajutorului și sprijinului” dușmanilor ei. Pentru a condamna, guvernul are nevoie fie de doi martori la același act manifest, fie de o mărturisire în instanță. Pedeapsa poate fi severă, dar nu poate fi extinsă pentru a pedepsi familia nevinovată a trădătorului.",
    history: "The Framers had just committed treason against the British Crown, and they knew from bitter history how easily rulers used treason charges to destroy political enemies. So they wrote the definition into the Constitution itself, made it deliberately hard to prove, and banned \"corruption of blood,\" the old English practice of punishing a traitor's descendants. It is the Constitution's clearest attempt to lock a dangerous power away from future abuse.",
    historyRo: "Fondatorii tocmai comiseseră trădare împotriva Coroanei britanice și știau din istoria amară cât de ușor foloseau conducătorii acuzațiile de trădare pentru a-și distruge dușmanii politici. Așa că au scris definiția chiar în Constituție, au făcut-o deliberat greu de dovedit și au interzis „coruperea sângelui”, vechea practică engleză de a pedepsi descendenții unui trădător. E cea mai clară încercare a Constituției de a încuia o putere periculoasă departe de abuzul viitor.",
    cases: [
      { name: "Cramer v. United States", year: "1945", note: "The two-witness rule is strict: each witness must testify to the same overt act of assistance.", noteRo: "Regula celor doi martori e strictă: fiecare martor trebuie să depună mărturie despre același act manifest de ajutor." },
      { name: "Ex parte Bollman", year: "1807", note: "Merely conspiring is not \"levying War\"; there must be an actual assemblage of force.", noteRo: "Simpla conspirație nu e „purtarea de război”; trebuie să existe o adunare efectivă de forță." },
    ],
    examples: "Treason prosecutions are extremely rare in American history, precisely because the bar set here is so high, and prosecutors almost always charge sedition, espionage, or terrorism instead, crimes that are easier to prove. The narrow definition is why even notorious enemies of the state are usually tried under other laws.",
    examplesRo: "Urmăririle pentru trădare sunt extrem de rare în istoria americană, tocmai fiindcă pragul stabilit aici e atât de ridicat, iar procurorii acuză aproape întotdeauna sediție, spionaj sau terorism în schimb, infracțiuni mai ușor de dovedit. Definiția restrânsă e motivul pentru care chiar și dușmani notorii ai statului sunt de obicei judecați sub alte legi.",
    debates: "\"Aid and Comfort\" and what counts as \"levying War\" resurface in every era's arguments over sedition, insurrection, and political violence, most recently in debates over the events of January 6, 2021. The tension is perennial: the definition is narrow by design to protect dissent and prevent abuse, yet that same narrowness frustrates those who want to brand modern enemies of the state as traitors.",
    debatesRo: "„Ajutor și sprijin” și ce înseamnă „purtarea de război” reapar în argumentele fiecărei epoci despre sediție, insurecție și violență politică, cel mai recent în dezbaterile despre evenimentele din 6 ianuarie 2021. Tensiunea e perenă: definiția e restrânsă prin proiectare pentru a proteja disidența și a preveni abuzul, dar aceeași îngustime îi frustrează pe cei care vor să-i eticheteze pe dușmanii moderni ai statului drept trădători.",
  },

  // ── Article IV ───────────────────────────────────────────────────────────────
  "art4-s1": {
    plain: "Every state must give \"full faith and credit\" to the public acts, records, and court judgments of every other state. In plain terms, a valid court ruling, marriage license, or official record from one state has to be recognized across all the others, and Congress can set the rules for how that works.",
    plainRo: "Fiecare stat trebuie să acorde „credință și încredere deplină” actelor publice, registrelor și hotărârilor judecătorești ale oricărui alt stat. În termeni simpli, o hotărâre judecătorească validă, o licență de căsătorie sau un act oficial dintr-un stat trebuie recunoscute în toate celelalte, iar Congresul poate stabili regulile pentru cum funcționează asta.",
    history: "This clause is the connective tissue that turns fifty separate legal systems into one country: without it, a debt won or a judgment entered in one state could be ignored the moment someone crossed a state line. It was a direct upgrade over the weak version in the Articles of Confederation, and Congress has used its power under the clause to standardize how state judgments and records are proved and enforced everywhere.",
    historyRo: "Această clauză e țesutul conjunctiv care transformă cincizeci de sisteme juridice separate într-o singură țară: fără ea, o datorie câștigată sau o hotărâre pronunțată într-un stat ar putea fi ignorată în momentul în care cineva trece granița unui stat. A fost o îmbunătățire directă față de versiunea slabă din Articolele Confederației, iar Congresul și-a folosit puterea din clauză pentru a standardiza modul în care hotărârile și registrele statale sunt dovedite și aplicate pretutindeni.",
    cases: [
      { name: "Williams v. North Carolina", year: "1942", note: "Wrestled with when one state must honor another's divorce decree.", noteRo: "S-a luptat cu momentul în care un stat trebuie să onoreze decretul de divorț al altuia." },
      { name: "Obergefell v. Hodges", year: "2015", note: "Required states to recognize same-sex marriages, decided mainly on the 14th Amendment.", noteRo: "A cerut statelor să recunoască căsătoriile între persoane de același sex, decis mai ales pe Amendamentul 14." },
    ],
    amendments: ["amend-14"],
    examples: "Driver's licenses honored across state lines, out-of-state court judgments that can be collected anywhere, child-custody and child-support orders that follow a family from state to state, and the recognition of marriages performed elsewhere all rest on Full Faith and Credit. It is why an official document does not lose its force at the border.",
    examplesRo: "Permisele de conducere onorate peste granițele statale, hotărârile judecătorești din afara statului care pot fi executate oriunde, ordinele de custodie și pensie alimentară care urmează o familie din stat în stat și recunoașterea căsătoriilor încheiate în altă parte se sprijină toate pe Credința și încrederea deplină. De aceea un document oficial nu își pierde forța la graniță.",
    debates: "The clause has repeatedly been the front line of the nation's fiercest social disputes: whether a state must recognize a marriage, a divorce, or a legal status it forbids at home. It ran through the same-sex marriage fights before Obergefell settled them, and it resurfaces in modern conflicts, such as when states take opposite positions on medical care or firearms permits and must decide how far to honor one another's laws.",
    debatesRo: "Clauza a fost în mod repetat linia întâi a celor mai aprige dispute sociale ale națiunii: dacă un stat trebuie să recunoască o căsătorie, un divorț sau un statut juridic pe care îl interzice acasă. A străbătut luptele pentru căsătoria între persoane de același sex înainte ca Obergefell să le soluționeze și reapare în conflicte moderne, precum când statele iau poziții opuse privind îngrijirea medicală sau permisele de arme și trebuie să decidă cât să onoreze legile celuilalt.",
  },
  "art4-s2": {
    plain: "A state must treat visiting citizens from other states largely the way it treats its own, it cannot brand out-of-staters as second-class. It must also extradite fugitives: someone charged with a crime in one state who flees to another must be sent back to face justice where the crime happened.",
    plainRo: "Un stat trebuie să trateze cetățenii în vizită din alte state în mare ca pe ai săi, nu îi poate marca pe cei din afara statului drept cetățeni de rangul doi. Trebuie de asemenea să extrădeze fugarii: cineva acuzat de o infracțiune într-un stat care fuge în altul trebuie trimis înapoi pentru a răspunde în fața justiției acolo unde s-a comis infracțiunea.",
    history: "The Privileges and Immunities Clause stops states from treating Americans from elsewhere as foreigners, a basic guarantee of national citizenship and free movement. This section originally also contained the notorious Fugitive Slave Clause, one of the Constitution's deepest compromises with slavery, which required escaped enslaved people to be returned even from free states, until the 13th Amendment erased it after the Civil War.",
    historyRo: "Clauza Privilegiilor și Imunităților împiedică statele să-i trateze pe americanii din altă parte ca pe străini, o garanție de bază a cetățeniei naționale și a liberei circulații. Această secțiune conținea inițial și infama Clauză a Sclavilor Fugari, unul dintre cele mai profunde compromisuri ale Constituției cu sclavia, care cerea returnarea persoanelor înrobite evadate chiar și din statele libere, până când Amendamentul 13 a șters-o după Războiul Civil.",
    cases: [
      { name: "Saenz v. Roe", year: "1999", note: "Protected the right to travel and to be treated equally soon after moving to a new state.", noteRo: "A protejat dreptul de a călători și de a fi tratat egal la scurt timp după mutarea într-un stat nou." },
      { name: "Toomer v. Witsell", year: "1948", note: "A state cannot charge out-of-staters vastly more for commercial licenses without good reason.", noteRo: "Un stat nu poate taxa mult mai mult pe cei din afara statului pentru licențe comerciale fără un motiv întemeiat." },
    ],
    amendments: ["amend-13", "amend-14"],
    examples: "Interstate extradition of criminal suspects, equal treatment of new residents, and limits on how much extra a state can charge non-residents for things like professional licenses all flow from this section. It is why a person cannot escape prosecution simply by driving across a state line.",
    examplesRo: "Extrădarea între state a suspecților, tratamentul egal al noilor rezidenți și limitele privind cât în plus poate taxa un stat pe nerezidenți pentru lucruri precum licențele profesionale decurg toate din această secțiune. De aceea o persoană nu poate scăpa de urmărire pur și simplu trecând granița unui stat cu mașina.",
    debates: "How much a state may favor its own residents, cheaper in-state college tuition, resident hunting and fishing licenses, preferences for local workers, is still litigated under the Privileges and Immunities Clause, which allows some favoritism but not economic protectionism against fellow Americans. Extradition, once thought automatic, has drawn fresh attention as states clash over enforcing one another's more controversial criminal laws.",
    debatesRo: "Cât poate un stat să-și favorizeze proprii rezidenți, taxe de studii mai mici pentru localnici, permise de vânătoare și pescuit pentru rezidenți, preferințe pentru lucrătorii locali, e încă litigat sub Clauza Privilegiilor și Imunităților, care permite un anumit favoritism, dar nu protecționism economic împotriva concetățenilor americani. Extrădarea, cândva considerată automată, a atras atenție proaspătă pe măsură ce statele se ciocnesc privind aplicarea legilor penale mai controversate ale celuilalt.",
  },
  "art4-s3": {
    plain: "Congress admits new states into the Union and governs the federal territories and property that do not belong to any state. A new state cannot be carved out of an existing one without that state's consent, so no region can be split off against a state's will.",
    plainRo: "Congresul admite state noi în Uniune și guvernează teritoriile și proprietatea federală care nu aparțin niciunui stat. Un stat nou nu poate fi decupat dintr-unul existent fără consimțământul acelui stat, așa că nicio regiune nu poate fi desprinsă împotriva voinței unui stat.",
    history: "This clause let the United States grow from thirteen states clinging to the Atlantic coast to a continental nation of fifty, and crucially it admitted new states as full equals of the original thirteen, not as subordinate colonies, a radical break with every empire before it. The territory power gave Congress authority over vast federal lands, an authority that shaped westward expansion and still governs enormous public holdings today.",
    historyRo: "Această clauză a permis Statelor Unite să crească de la treisprezece state agățate de coasta Atlanticului la o națiune continentală de cincizeci și, esențial, a admis state noi ca egale depline ale celor treisprezece originale, nu ca pe colonii subordonate, o ruptură radicală cu orice imperiu de dinainte. Puterea asupra teritoriilor a dat Congresului autoritate asupra unor întinse pământuri federale, o autoritate care a modelat expansiunea spre vest și guvernează încă enorme proprietăți publice azi.",
    cases: [
      { name: "Coyle v. Smith", year: "1911", note: "New states enter on an \"equal footing\" with the original states and cannot be admitted on lesser terms.", noteRo: "Statele noi intră pe „picior de egalitate” cu statele originale și nu pot fi admise în condiții inferioare." },
      { name: "Insular Cases", year: "1901", note: "Controversially held that the Constitution does not fully apply of its own force to overseas territories.", noteRo: "Au susținut controversat că Constituția nu se aplică pe deplin prin propria forță teritoriilor de peste mări." },
    ],
    examples: "The path to statehood for territories like Alaska and Hawaii ran through this clause, and today the debates over statehood for Washington, D.C. and Puerto Rico turn on it as well. Federal control of national parks, forests, and huge tracts of Western land also rests on the territory-and-property power here.",
    examplesRo: "Drumul spre statalitate al teritoriilor precum Alaska și Hawaii a trecut prin această clauză, iar azi dezbaterile despre statalitatea Washington D.C. și Puerto Rico depind de asemenea de ea. Controlul federal al parcurilor naționale, pădurilor și uriașelor întinderi de pământ din Vest se sprijină de asemenea pe puterea asupra teritoriilor și proprietății de aici.",
    debates: "Whether Washington, D.C. or Puerto Rico should become states is a live and partisan political question governed by this section, tangled up in the balance of power in the Senate. The status of overseas territories, and the old, much-criticized Insular Cases holding that the full Constitution does not automatically follow the flag, remains a simmering constitutional and moral controversy over how millions of Americans are governed without full representation.",
    debatesRo: "Dacă Washington D.C. sau Puerto Rico ar trebui să devină state e o chestiune politică vie și partizană guvernată de această secțiune, încurcată în echilibrul de putere din Senat. Statutul teritoriilor de peste mări, și vechile, mult criticatele Insular Cases care susțin că întreaga Constituție nu urmează automat steagul, rămâne o controversă constituțională și morală mocnită despre cum sunt guvernate milioane de americani fără reprezentare deplină.",
  },
  "art4-s4": {
    plain: "The federal government guarantees every state a \"republican form of government,\" meaning representative self-rule rather than monarchy or dictatorship. It also promises to protect the states from invasion and, if a state asks, from internal violence it cannot handle alone.",
    plainRo: "Guvernul federal garantează fiecărui stat o „formă de guvernare republicană”, adică autoguvernare reprezentativă, nu monarhie sau dictatură. Promite de asemenea să protejeze statele de invazie și, dacă un stat cere, de violența internă pe care nu o poate gestiona singur.",
    history: "The Guarantee Clause is a promise that no state may quietly slide into monarchy, dictatorship, or mob rule, that whatever happens locally, self-government survives. But from early on the Supreme Court decided that what counts as \"republican\" is a political question for Congress and the President to answer, not the courts, which is why the clause is rarely enforced by judges despite its sweeping language.",
    historyRo: "Clauza Garanției e o promisiune că niciun stat nu poate aluneca discret în monarhie, dictatură sau guvernarea gloatei, că orice s-ar întâmpla local, autoguvernarea supraviețuiește. Dar de timpuriu Curtea Supremă a decis că ce înseamnă „republican” e o chestiune politică la care răspund Congresul și Președintele, nu instanțele, motiv pentru care clauza e rar aplicată de judecători în ciuda limbajului ei cuprinzător.",
    cases: [
      { name: "Luther v. Borden", year: "1849", note: "What counts as a \"republican\" government is a political question for Congress, not the courts.", noteRo: "Ce înseamnă un guvern „republican” e o chestiune politică pentru Congres, nu pentru instanțe." },
      { name: "Baker v. Carr", year: "1962", note: "Routed around the Guarantee Clause, letting courts hear apportionment cases under Equal Protection instead.", noteRo: "A ocolit Clauza Garanției, permițând instanțelor să judece cazurile de repartizare sub Egala Protecție în schimb." },
    ],
    examples: "Federal troops sent to protect a state, from quelling insurrections to responding to disasters, and the basic promise that every state must run on representative government, rest on this clause. It is the constitutional backdrop to the federal role whenever order breaks down within a state.",
    examplesRo: "Trupele federale trimise să protejeze un stat, de la înăbușirea insurecțiilor la răspunsul la dezastre, și promisiunea de bază că fiecare stat trebuie să funcționeze pe guvernare reprezentativă, se sprijină pe această clauză. E fundalul constituțional al rolului federal ori de câte ori ordinea se prăbușește într-un stat.",
    debates: "Because the courts treat it as a political question, the Guarantee Clause is a sleeping giant: scholars periodically argue it could be revived to attack extreme partisan gerrymandering, or ballot-initiative systems, as departures from truly \"republican\" government. Whether judges should ever enforce it, or leave its meaning entirely to the elected branches, is a long-running and unresolved debate.",
    debatesRo: "Fiindcă instanțele o tratează ca pe o chestiune politică, Clauza Garanției e un uriaș adormit: cercetătorii argumentează periodic că ar putea fi reînviată pentru a ataca gerrymandering-ul partizan extrem, sau sistemele de inițiativă cetățenească, ca abateri de la o guvernare cu adevărat „republicană”. Dacă judecătorii ar trebui vreodată să o aplice, sau să-i lase sensul în întregime ramurilor alese, e o dezbatere îndelungată și nerezolvată.",
  },

  // ── Article V ────────────────────────────────────────────────────────────────
  art5: {
    plain: "The Constitution can be changed, but only through a demanding two-stage process. An amendment is first proposed, either by a two-thirds vote of both houses of Congress or by a convention called by two-thirds of the states, and then it must be ratified by three-fourths of the states. One rule is placed beyond amendment: no state can be stripped of its equal vote in the Senate without agreeing.",
    plainRo: "Constituția poate fi schimbată, dar numai printr-un proces exigent în două etape. Un amendament e mai întâi propus, fie de un vot de două treimi al ambelor camere ale Congresului, fie de o convenție cerută de două treimi din state, și apoi trebuie ratificat de trei sferturi din state. O regulă e plasată dincolo de amendament: niciun stat nu poate fi privat de votul său egal în Senat fără acord.",
    history: "Article V threads a needle: the Framers had lived under the Articles of Confederation, which required unanimous consent to change and so could never be fixed, yet they also feared a constitution too easily rewritten by passing majorities. Their answer was a process hard but not impossible, requiring broad and lasting consensus across the country. That deliberate difficulty is why the document has been amended only 27 times in more than 230 years.",
    historyRo: "Articolul V trece printr-un ac: Fondatorii trăiseră sub Articolele Confederației, care cereau consimțământ unanim pentru schimbare și deci nu puteau fi niciodată reparate, dar se temeau și de o constituție prea ușor rescrisă de majorități trecătoare. Răspunsul lor a fost un proces greu dar nu imposibil, cerând un consens larg și durabil în toată țara. Această dificultate deliberată e motivul pentru care documentul a fost modificat doar de 27 de ori în peste 230 de ani.",
    cases: [
      { name: "Coleman v. Miller", year: "1939", note: "Many questions about the amendment process, like ratification deadlines, are political questions left to Congress.", noteRo: "Multe întrebări despre procesul de amendare, precum termenele de ratificare, sunt chestiuni politice lăsate Congresului." },
      { name: "Dillon v. Gloss", year: "1921", note: "Congress may attach a reasonable time limit for ratifying a proposed amendment.", noteRo: "Congresul poate atașa o limită de timp rezonabilă pentru ratificarea unui amendament propus." },
    ],
    examples: "All 27 amendments were proposed by Congress and then ratified by the states; the alternative route, a convention of states, has never once been used, though state campaigns to trigger one flare up periodically. The Equal Rights Amendment's long, unresolved journey shows how easily an amendment can stall short of three-fourths of the states.",
    examplesRo: "Toate cele 27 de amendamente au fost propuse de Congres și apoi ratificate de state; ruta alternativă, o convenție a statelor, nu a fost folosită niciodată, deși campaniile statale de a declanșa una izbucnesc periodic. Călătoria lungă și nerezolvată a Amendamentului Drepturilor Egale arată cât de ușor un amendament se poate bloca sub pragul de trei sferturi din state.",
    debates: "Whether to call an Article V \"convention of states\" is a recurring and contested proposal, exciting to reformers who despair of Congress ever amending itself, and alarming to critics who fear a \"runaway convention\" that could rewrite far more than intended, since the Constitution gives almost no rules for how such a convention would work. Deep questions also linger about ratification deadlines and whether a state may rescind a prior yes.",
    debatesRo: "Dacă să se convoace o „convenție a statelor” în baza Articolului V e o propunere recurentă și disputată, incitantă pentru reformatorii care disperă că Congresul se va amenda vreodată singur, și alarmantă pentru criticii care se tem de o „convenție scăpată de sub control” care ar putea rescrie mult mai mult decât s-a intenționat, fiindcă Constituția nu dă aproape nicio regulă despre cum ar funcționa o astfel de convenție. Întrebări profunde persistă și despre termenele de ratificare și dacă un stat își poate retrage un da anterior.",
  },

  // ── Article VI ───────────────────────────────────────────────────────────────
  art6: {
    plain: "The Constitution, federal laws made under it, and treaties are together \"the supreme Law of the Land,\" overriding any state law that conflicts with them. Every federal and state official must swear an oath to support the Constitution, and, strikingly for 1787, no religious test may ever be required to hold office.",
    plainRo: "Constituția, legile federale făcute în baza ei și tratatele sunt împreună „legea supremă a țării”, având prioritate față de orice lege statală care le contrazice. Fiecare oficial federal și statal trebuie să depună un jurământ de a susține Constituția și, remarcabil pentru 1787, niciun test religios nu poate fi cerut vreodată pentru a deține o funcție.",
    history: "The Supremacy Clause is what actually makes federalism work: when state and federal law collide, federal law wins, and state judges are bound to enforce that even against their own state's statutes. Without it, the whole structure would dissolve into thirteen, then fifty, competing sovereignties. The ban on religious tests was quietly radical in 1787, when many states still required officeholders to be Protestant or at least Christian; it planted the seed of a secular national government.",
    historyRo: "Clauza Supremației e ceea ce face de fapt federalismul să funcționeze: când legea statală și cea federală se ciocnesc, câștigă legea federală, iar judecătorii statali sunt obligați să o aplice chiar și împotriva legilor propriului stat. Fără ea, întreaga structură s-ar dizolva în treisprezece, apoi cincizeci de suveranități concurente. Interzicerea testelor religioase era discret radicală în 1787, când multe state cereau ca funcționarii să fie protestanți sau cel puțin creștini; a plantat sămânța unui guvern național secular.",
    cases: [
      { name: "McCulloch v. Maryland", year: "1819", note: "A state cannot tax or obstruct a valid federal institution; federal law is supreme.", noteRo: "Un stat nu poate impozita sau obstrucționa o instituție federală validă; legea federală e supremă." },
      { name: "Gibbons v. Ogden", year: "1824", note: "Valid federal law preempts and displaces conflicting state law.", noteRo: "Legea federală validă are prioritate față de și înlocuiește legea statală contrară." },
      { name: "Cooper v. Aaron", year: "1958", note: "States must obey the Supreme Court's constitutional rulings; they cannot nullify them.", noteRo: "Statele trebuie să se supună deciziilor constituționale ale Curții Supreme; nu le pot anula." },
    ],
    amendments: ["amend-1", "amend-10"],
    examples: "Federal preemption of state law, when a federal statute overrides state rules on everything from drug approval to immigration to consumer protection, is decided under the Supremacy Clause every year. The no-religious-test rule is why an oath of office in America asks only for loyalty to the Constitution, never to a faith.",
    examplesRo: "Prioritatea federală asupra legii statale, când o lege federală înlocuiește regulile statale de la aprobarea medicamentelor la imigrație și protecția consumatorilor, e decisă sub Clauza Supremației în fiecare an. Regula fără test religios e motivul pentru care un jurământ de funcție în America cere doar loialitate față de Constituție, niciodată față de o credință.",
    debates: "How much room states have to chart their own course, legalizing cannabis the federal government still bans, setting their own climate or immigration policies, resisting federal mandates, is a constant supremacy-and-federalism tension. The old, discredited theories of \"nullification\" and \"interposition,\" the idea that a state may void federal law it deems unconstitutional, still echo whenever a state defies Washington, even though Cooper v. Aaron rejected them.",
    debatesRo: "Cât spațiu au statele să-și traseze propriul drum, legalizând canabisul pe care guvernul federal încă îl interzice, stabilind propriile politici climatice sau de imigrație, rezistând mandatelor federale, e o tensiune constantă între supremație și federalism. Vechile teorii discreditate ale „nulificării” și „interpunerii”, ideea că un stat poate anula legea federală pe care o consideră neconstituțională, încă răsună ori de câte ori un stat sfidează Washingtonul, deși Cooper v. Aaron le-a respins.",
  },

  // ── Article VII ──────────────────────────────────────────────────────────────
  art7: {
    plain: "The Constitution would take effect once nine of the thirteen states ratified it, not all thirteen, and it records that it was signed in Philadelphia on September 17, 1787. In effect, this short article is the document's own instructions for how to come to life.",
    plainRo: "Constituția urma să intre în vigoare odată ce nouă din cele treisprezece state o ratificau, nu toate treisprezece, și consemnează că a fost semnată la Philadelphia pe 17 septembrie 1787. În fapt, acest scurt articol e propria instrucțiune a documentului despre cum să prindă viață.",
    history: "Requiring only nine states rather than unanimous consent was itself a bold, arguably extralegal move: the Articles of Confederation demanded unanimity to change, so the Framers effectively bypassed the existing rules to launch a new government, wagering that success would ratify their audacity. Choosing ratification by special state conventions, elected by the people, rather than by existing state legislatures, was equally deliberate, rooting the new charter directly in popular consent and echoing the Preamble's \"We the People.\"",
    historyRo: "Cerința de doar nouă state în loc de consimțământ unanim a fost ea însăși o mișcare îndrăzneață, discutabil extralegală: Articolele Confederației cereau unanimitate pentru schimbare, așa că Fondatorii au ocolit efectiv regulile existente pentru a lansa un guvern nou, pariind că succesul le va ratifica îndrăzneala. Alegerea ratificării prin convenții statale speciale, alese de popor, nu prin legislaturile statale existente, a fost la fel de deliberată, întemeind noua cartă direct pe consimțământul popular și în ecoul „Noi, Poporul” din Preambul.",
    cases: [],
    examples: "September 17 is now marked every year as Constitution Day, commemorating the signing this article records. Delaware's quick ratification made it \"the First State,\" and the fierce state-by-state ratification debates that followed produced the Federalist Papers and the promise of a Bill of Rights.",
    examplesRo: "17 septembrie e marcat acum în fiecare an ca Ziua Constituției, comemorând semnarea pe care o consemnează acest articol. Ratificarea rapidă a statului Delaware l-a făcut „Primul Stat”, iar dezbaterile aprige de ratificare stat cu stat care au urmat au produs Federalist Papers și promisiunea unei Declarații a Drepturilor.",
    debates: "The decision to ratify through popularly elected conventions rather than state legislatures was a quiet revolution in political theory, deliberately rooting the Constitution in the people themselves so it could claim to be superior to ordinary state law. Historians still debate whether the Convention exceeded its authority, it had been called only to amend the Articles, not replace them, making the founding itself a kind of lawful coup that succeeded because the people ratified it.",
    debatesRo: "Decizia de a ratifica prin convenții alese de popor, nu prin legislaturi statale, a fost o revoluție tăcută în teoria politică, întemeind deliberat Constituția pe poporul însuși pentru a putea pretinde că e superioară legii statale obișnuite. Istoricii încă dezbat dacă Convenția și-a depășit autoritatea, fusese convocată doar pentru a amenda Articolele, nu pentru a le înlocui, făcând din fondarea însăși un fel de lovitură legală care a reușit fiindcă poporul a ratificat-o.",
  },
};
